#!/bin/sh
# GENERATED by `fabricx generate`. Kernel plumbing for VXLAN-EVPN on leaf1.
# Runs BEFORE FRR starts (see the clab `cmd`): if FRR boots first, it can bind the L3VNI to an
# automatically created BGP instance and never originate Type-5 routes (seen on CI).
set -e
# r = retry a step for up to 5 s. Once (leaf1, Mac, 2026-11-23) a device created one line earlier was "not found";
# the script exited, Docker restarted the container, and the restart wiped the links Containerlab had just plugged in.
r() { n=0; until "$@"; do n=$((n+1)); [ "$n" -ge 25 ] && return 1; sleep 0.2; done; }
sysctl -qw net.ipv4.ip_forward=1
sysctl -qw net.ipv4.fib_multipath_hash_policy=1
sysctl -qw net.ipv4.conf.all.rp_filter=0 net.ipv4.conf.default.rp_filter=0

# --- VRF RED: routing table + L3VNI 50001 (used for routed traffic between leaves)
ip link add RED type vrf table 1001
r ip link set RED up
ip link add br50001 type bridge
ip link add vx50001 type vxlan id 50001 dstport 4789 local 10.0.0.11 df set nolearning
r ip link set vx50001 mtu 1500 master br50001
r ip link set br50001 master RED
r ip link set br50001 up
r ip link set vx50001 up

# --- VLAN 10: L2VNI 10010, anycast gateway 10.10.10.1, in VRF RED
ip link add br10 type bridge
ip link add vx10010 type vxlan id 10010 dstport 4789 local 10.0.0.11 df set nolearning
r ip link set vx10010 mtu 1500 master br10
r ip link set br10 address 02:fa:b0:00:00:01
r ip link set br10 master RED
r ip addr add 10.10.10.1/24 dev br10
r ip link set br10 up
r ip link set vx10010 up

# --- VLAN 20: L2VNI 10020, anycast gateway 10.20.20.1, in VRF RED
ip link add br20 type bridge
ip link add vx10020 type vxlan id 10020 dstport 4789 local 10.0.0.11 df set nolearning
r ip link set vx10020 mtu 1500 master br20
r ip link set br20 address 02:fa:b0:00:00:01
r ip link set br20 master RED
r ip addr add 10.20.20.1/24 dev br20
r ip link set br20 up
r ip link set vx10020 up
